  async function renderDeletionHistoryNotice() {
    if (!elements.deletionHistoryNotice) return;
    let level = 0;
    let count = 0;
    try {
      count = await getTombstoneCount();
      level = tombstoneWarningLevel(count);
    } catch {
      level = 0;
    }
    if (level === 0) {
      elements.deletionHistoryNotice.classList.add("hidden");
      return;
    }
    elements.deletionHistoryNotice.classList.remove("hidden");
    if (elements.deletionHistoryText) {
      elements.deletionHistoryText.textContent = level >= 2 ? `Deletion history is large (${count} entries). Clearing it frees sync space; a device that has been offline since one of those deletions could re-add that item.` : `Deletion history has grown to ${count} entries. You may want to clear it. A device offline since a cleared deletion could re-add that item.`;
    }
  }
  function formatSince(ts) {
    if (!ts) return null;
    const s = Math.floor((Date.now() - ts) / 1e3);
    if (s < 45) return "just now";
    const m = Math.floor(s / 60);
    if (m < 60) return `${m} minute${m === 1 ? "" : "s"} ago`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h} hour${h === 1 ? "" : "s"} ago`;
    const d = Math.floor(h / 24);
    if (d < 30) return `${d} day${d === 1 ? "" : "s"} ago`;
    const mo = Math.floor(d / 30);
    return `${mo} month${mo === 1 ? "" : "s"} ago`;
  }
  function renderBackupFreshness(status) {
    const el = elements.backupFreshness;
    if (!el) return;
    el.classList.remove("status-line--warn");
    if (status.dirty) {
      el.textContent = status.lastBackupAt ? `\u26A0 Accounts changed since your last backup (${formatSince(status.lastBackupAt)}) \u2014 back up now.` : "\u26A0 You have accounts but no backup yet \u2014 back up now.";
      el.classList.add("status-line--warn");
    } else if (status.lastBackupAt) {
      el.textContent = `Last backed up ${formatSince(status.lastBackupAt)}.`;
    } else {
      el.textContent = "No backup yet.";
    }
  }
